        codePoint -= 0x10000;
        sb.append((char) ((codePoint >> 10) + 0xD800));
        sb.append((char) ((codePoint & 0x3FF) + 0xDC00));
        return i + 4;
    }
    // Invalid byte, append placeholder and advance one
    sb.append('?');
    return i + 1;
}

