private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int startIndex = i;
    int initialPos = bb.position();
    int firstByte = bb.get() & 0xFF;
    int codePoint;
    if (firstByte <= 0x7F) { // 1-byte (ASCII)
        codePoint = firstByte;
    } else if ((firstByte & 0xE0) == 0xC0) { // 2-byte sequence
        int second = bb.get() & 0xFF;
        codePoint = ((firstByte & 0x1F) << 6) | (second & 0x3F);
    } else if ((firstByte & 0xF0) == 0xE0) { // 3-byte sequence
        int second = bb.get() & 0xFF;
        int third  = bb.get() & 0xFF;
        codePoint = ((firstByte & 0x0F) << 12) | ((second & 0x3F) << 6) | (third & 0x3F);
    } else if ((firstByte & 0xF8) == 0xF0) { // 4-byte sequence
        int second = bb.get() & 0xFF;
        int third  = bb.get() & 0xFF;
        int fourth = bb.get() & 0xFF;
        codePoint = ((firstByte & 0x07) << 18) | ((second & 0x3F) << 12)
                    | ((third & 0x3F) << 6) | (fourth & 0x3F);
        if (codePoint > 0xFFFF) { // surrogate pair
            int high = ((codePoint - 0x10000) >> 10) + 0xD800;
            int low  = ((codePoint - 0x10000) & 0x3FF) + 0xDC00;
            sb.append((char) high);
            sb.append((char) low);
            return startIndex + (bb.position() - initialPos);
        }
    } else {
        // Invalid leading byte; use replacement character
        codePoint = 0xFFFD;
    }
    sb.append((char) codePoint);
    return startIndex + (bb.position() - initialPos);
}

