private int parseEndOfLine(String headerPart,int end){
    for(int i = end;i < headerPart.length() - 1;i++){
        if(headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n'){
            return i;
        }
    }
    return -1;
}

private int parseEndOfLine(String headerPart, int end){
    int len = headerPart.length();
    if (len <= end) return -1;
    int i = end + 1;
    while (i < len - 1) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
        i++;
    }
    return -1;
}

