IsomorphicGraphMapping<V,E> function ( final Graph<V,E> graph ) { 
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<V,E>(graph, graph); 
    for ( V v : graph.vertexSet() ) { 
        mapping.mapVertex( v, v ); 
    } 
    for ( E e : graph.edgeSet() ) { 
        mapping.mapEdge( e, e ); 
    } 
    return mapping; 
}

public static <V,E>IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<>(graph, graph);
    for (V v : graph.vertexSet()){
        mapping.addVertexMapping(v, v);
    }
    for (E e : graph.edgeSet()){
        mapping.addEdgeMapping(e, e);
    }
    return mapping;
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    // Create an identity mapping where each vertex and edge maps to itself
    Map<V,V> vertexMap = new HashMap<>();
    Map<E,E> edgeMap = new HashMap<>();
    for (V v : graph.getVertices()) {
        vertexMap.put(v, v);
    }
    for (E e : graph.getEdges()) {
        edgeMap.put(e, e);
    }
    return new IsomorphicGraphMapping<>(graph, graph, vertexMap, edgeMap);
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    if (file.isDirectory()) {
        // Schedule deletion of all files and directories in reverse order (children first)
        Path dirPath = file.toPath();
        try (Stream<Path> stream = Files.walk(dirPath)) {
            stream.sorted(Comparator.reverseOrder())
                  .forEach(p -> p.toFile().deleteOnExit());
        } catch (IOException e) {
            throw new IOException("Unable to schedule deletion of directory: " + file, e);
        }
    } else {
        file.deleteOnExit();
    }
}

