private static void deleteDirectoryOnExit(File dir) {
    File[] children = dir.listFiles();
    if (children != null) {
        for (File child : children) {
            if (child.isDirectory()) {
                deleteDirectoryOnExit(child);
            } else {
                child.deleteOnExit();
            }
        }
    }
    dir.deleteOnExit();
}

