protected void subAppend(LoggingEvent event){
    if (event == null) {
        throw new NullPointerException("LoggingEvent is null");
    }
    String msg = layout.format(event);
    try {
        writer.write(msg);
        if (!layout.ignoresThrowable()) {
            String[] stack = event.getThrowableStrRep();
            if (stack != null) {
                for (String s : stack) {
                    writer.write(s);
                }
            }
        }
        writer.flush();
    } catch (IOException e) {
        errorHandler.error("Failed to write log event", e, ErrorCode.WRITE_FAILURE);
    }
}

protected void subAppend(LoggingEvent event){
    if (event.getLevel().isGreaterOrEqual(Level.ERROR)) {
        logger.error(event.getRenderedMessage());
    } else {
        logger.info(event.getRenderedMessage());
    }
}

protected void subAppend(LoggingEvent event){
    try {
        String msg;
        if (this.getLayout() != null) {
            msg = this.getLayout().format(event);
        } else {
            msg = String.valueOf(event.getMessage());
        }
        if (this.writer != null) {
            this.writer.write(msg);
            this.writer.flush();
        } else if (this.out != null) {
            this.out.write(msg.getBytes());
            this.out.flush();
        } else {
            System.out.println(msg);
        }
    } catch (Exception e) {
        // ignore
    }
}

