public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof java.lang.reflect.ParameterizedType)) {
        return null;
    }
    java.lang.reflect.ParameterizedType pType = (java.lang.reflect.ParameterizedType) genericType;
    java.lang.reflect.Type[] typeArgs = pType.getActualTypeArguments();
    Class<?>[] result = new Class<?>[typeArgs.length];
    for (int i = 0; i < typeArgs.length; i++) {
        java.lang.reflect.Type t = typeArgs[i];
        Class<?> cls = null;
        if (t instanceof Class<?>) {
            cls = (Class<?>) t;
        } else if (t instanceof java.lang.reflect.ParameterizedType) {
            java.lang.reflect.Type raw = ((java.lang.reflect.ParameterizedType) t).getRawType();
            if (raw instanceof Class<?>) {
                cls = (Class<?>) raw;
            }
        } else if (t instanceof java.lang.reflect.WildcardType) {
            java.lang.reflect.Type[] bounds = ((java.lang.reflect.WildcardType) t).getUpperBounds();
            if (bounds.length > 0 && bounds[0] instanceof Class<?>) {
                cls = (Class<?>) bounds[0];
            }
        }
        if (cls == null) {
            return null;
        }
        result[i] = cls;
    }
    return result;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType){
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType paramType = (ParameterizedType) genericType;
    Type[] actualTypes = paramType.getActualTypeArguments();

    // Build a map of type variables to actual types for the target type hierarchy
    java.util.Map<TypeVariable<?>, Type> typeVarMap = new java.util.HashMap<>();

    // Traverse class hierarchy to fill the map
    java.util.Deque<Class<?>> stack = new java.util.ArrayDeque<>();
    stack.push(targetType);
    while (!stack.isEmpty()) {
        Class<?> cls = stack.pop();

        // Process superclass
        Type superType = cls.getGenericSuperclass();
        if (superType instanceof ParameterizedType) {
            ParameterizedType superParam = (ParameterizedType) superType;
            Class<?> superRaw = (Class<?>) superParam.getRawType();
            TypeVariable<?>[] superParams = superRaw.getTypeParameters();
            Type[] superArgs = superParam.getActualTypeArguments();
            for (int i = 0; i < superParams.length; i++) {
                typeVarMap.put(superParams[i], superArgs[i]);
            }
            stack.push(superRaw);
        } else if (superType instanceof Class<?>) {
            stack.push((Class<?>) superType);
        }

        // Process interfaces
        for (Type ifaceType : cls.getGenericInterfaces()) {
            if (ifaceType instanceof ParameterizedType) {
                ParameterizedType ifaceParam = (ParameterizedType) ifaceType;
                Class<?> ifaceRaw = (Class<?>) ifaceParam.getRawType();
                TypeVariable<?>[] ifaceParams = ifaceRaw.getTypeParameters();
                Type[] ifaceArgs = ifaceParam.getActualTypeArguments();
                for (int i = 0; i < ifaceParams.length; i++) {
                    typeVarMap.put(ifaceParams[i], ifaceArgs[i]);
                }
                stack.push(ifaceRaw);
            } else if (ifaceType instanceof Class<?>) {
                stack.push((Class<?>) ifaceType);
            }
        }
    }

    // Resolve each actual type argument to a raw Class
    Class<?>[] result = new Class<?>[actualTypes.length];
    for (int i = 0; i < actualTypes.length; i++) {
        Type t = actualTypes[i];
        Class<?> resolved = null;
        if (t instanceof Class<?>) {
            resolved = (Class<?>) t;
        } else if (t instanceof ParameterizedType) {
            resolved = (Class<?>) ((ParameterizedType) t).getRawType();
        } else if (t instanceof TypeVariable<?>) {
            Type mapped = typeVarMap.get(t);
            if (mapped instanceof Class<?>) {
                resolved = (Class<?>) mapped;
            } else if (mapped instanceof ParameterizedType) {
                resolved = (Class<?>) ((ParameterizedType) mapped).getRawType();
            }
        }

        if (resolved == null) {
            return null; // cannot resolve to a concrete Class
        }
        result[i] = resolved;
    }
    return result;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    return resolveRawArguments(resolveGenericType(genericType, targetType), targetType);
}

