public Mappings diffStructure(String tableName, Mappings mappings){
    // Obtain the current mapping for the table (history mapping from current index)
    Mappings current = this.getMappingForTable(tableName);
    // Create a new Mappings object to hold the differences
    Mappings diff = new Mappings();
    // Iterate over the fields in the current mapping
    for (Map.Entry<String, Field> entry : current.getFields().entrySet()){
        String fieldName = entry.getKey();
        // Skip the special `_source` field to avoid update conflicts
        if ("_source".equals(fieldName)) continue;
        // If the field does not exist in the input mappings, add it to the diff
        if (!mappings.getFields().containsKey(fieldName)){
            diff.getFields().put(fieldName, entry.getValue());
        }
    }
    return diff;
}

Mappings diffStructure(String tableName, Mappings mappings) {
