        // If there is no existing mapping, just return the input (excluding _source)
        Mappings result = new Mappings();
        for (Map.Entry<String, Object> entry : mappings.getMappings().entrySet()) {
            String field = entry.getKey();
            if (!"_source".equals(field)) {
                result.addField(field, entry.getValue());
            }
        }
        return result;
    }

    // Compute the difference
    Mappings diff = new Mappings();
    for (Map.Entry<String, Object> entry : mappings.getMappings().entrySet()) {
        String fieldName = entry.getKey();
        if ("_source".equals(fieldName)) {
            continue; // skip source field to avoid update conflicts
        }
        if (!current.containsField(fieldName)) {
            diff.addField(fieldName, entry.getValue());
        }
    }
    return diff;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the historical mapping for the table
    Mappings history = getHistoryMapping(tableName); // assumed helper method
    Mappings diff = new Mappings();

    if (history == null) {
        return diff; // nothing to compare against
    }

    // Iterate over each type defined in the historical mapping
    for (String typeName : history.getTypes()) {
        TypeMapping hType = history.getType(typeName);
        TypeMapping cType = (mappings != null) ? mappings.getType(typeName) : null;

        // Historic and current property maps
        Map<String, Property> hProps = hType.getProperties();
        Map<String, Property> cProps = (cType != null) ? cType.getProperties() : Collections.emptyMap();

        // Prepare the corresponding type in the diff object
        TypeMapping diffType = diff.getType(typeName);
        if (diffType == null) {
            diff.addType(typeName);
            diffType = diff.getType(typeName);
        }

        // Compare each field in the historic mapping against the current mapping
        for (Map.Entry<String, Property> entry : hProps.entrySet()) {
            String fieldName = entry.getKey();
            // Skip the reserved '_source' field
            if ("_source".equals(fieldName)) {
                continue;
            }
            // If the field is missing in the current mapping, add it to the diff
            if (!cProps.containsKey(fieldName)) {
                diffType.addField(fieldName, entry.getValue());
            }
        }
    }
    return diff;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the stored mapping for the given table (history mapping from current index)
    Mappings storedMappings = this.getStoredMappings(tableName);
    if (storedMappings == null) {
        return new Mappings();
    }

    // Build a new mapping containing only those fields that are not present in the input mappings
    // and exclude the "_source" configuration to avoid update conflicts.
    Mappings diff = new Mappings();
    for (Map.Entry<String, Object> entry : storedMappings.entrySet()) {
        String key = entry.getKey();
        if ("_source".equals(key) || mappings.containsKey(key)) {
            continue;
        }
        diff.put(key, entry.getValue());
    }
    return diff;
}

