public long readLong(final int offset){
    return ((long)(getByte(offset)   & 0xFF) << 56) |
           ((long)(getByte(offset+1) & 0xFF) << 48) |
           ((long)(getByte(offset+2) & 0xFF) << 40) |
           ((long)(getByte(offset+3) & 0xFF) << 32) |
           ((long)(getByte(offset+4) & 0xFF) << 24) |
