static long compressTimeBucket(long timeBucket,int dayStep){
    long year = timeBucket / 10000;
    long month = (timeBucket % 10000) / 100;
    long day = timeBucket % 100;
    long newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000 + month * 100 + newDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        return timeBucket;
    }
    long year = timeBucket / 10000;
    long month = (timeBucket % 10000) / 100;
    long day = timeBucket % 100;
    long newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000 + month * 100 + newDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    int year = (int)(timeBucket / 10000);
    int month = (int)((timeBucket / 100) % 100);
    int day = (int)(timeBucket % 100);
    java.time.LocalDate date = java.time.LocalDate.of(year, month, day);
    int offset = (date.getDayOfMonth() - 1) % dayStep;
    java.time.LocalDate bucketStart = date.minusDays(offset);
    return bucketStart.getYear() * 10000L + bucketStart.getMonthValue() * 100L + bucketStart.getDayOfMonth();
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null || len <= 0) {
        return 0;
    }
    int count = 0;
    int start = index;
    int end = Math.min(index + len, str.length());
    int i = start;
    while (i < end) {
        int cp = str.codePointAt(i);
        int bytes;
        if (cp <= 0x7F) {
            bytes = 1;
        } else if (cp <= 0x7FF) {
            bytes = 2;
        } else if (cp <= 0xFFFF) {
            bytes = 3;
        } else {
            bytes = 4;
        }
        count += bytes;
        i += Character.charCount(cp);
    }
    return count;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        return 0;
    }
    int strLen = str.length();
    int start = index;
    if (start < 0) {
        start = 0;
    }
    int length = len;
    if (length < 0) {
        length = 0;
    }
    int end = start + length;
    if (end > strLen) {
        end = strLen;
    }
    int size = 0;
    for (int i = start; i < end; ) {
        char c = str.charAt(i++);
        if (c < 0x80) {
            size++;
        } else if (c < 0x800) {
            size += 2;
        } else {
            if (Character.isHighSurrogate(c) && i < end) {
                char low = str.charAt(i);
                if (Character.isLowSurrogate(low)) {
                    i++; // consume low surrogate
                    size += 4;
                    continue;
                }
            }
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    int size = 0;
    int i = 0;
    while (i < len) {
        char ch = str.charAt(index + i);
        int cp;
        if (Character.isHighSurrogate(ch) && i + 1 < len) {
            char lo = str.charAt(index + i + 1);
            if (Character.isLowSurrogate(lo)) {
                cp = Character.toCodePoint(ch, lo);
                i++; // skip low surrogate
            } else {
                cp = ch;
            }
        } else {
            cp = ch;
        }
        if (cp <= 0x7F) {
            size++;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
        i++;
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        int cp;
        if (Character.isHighSurrogate(ch) && i + 1 < end) {
            char next = str.charAt(i + 1);
            if (Character.isLowSurrogate(next)) {
                cp = Character.toCodePoint(ch, next);
                i++;
            } else {
                cp = ch;
            }
        } else {
            cp = ch;
        }
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

