public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int len = str.length();
    // Maximum UTF-8 length per code point is 4 bytes
    byte[] buffer = new byte[len * 4];
    int pos = 0;
    for (int i = 0; i < len; i++) {
        int codePoint = str.charAt(i);
        if (codePoint < 0x80) { // 1 byte
            buffer[pos++] = (byte) codePoint;
        } else if (codePoint < 0x800) { // 2 bytes
            buffer[pos++] = (byte) (0xC0 | (codePoint >> 6));
            buffer[pos++] = (byte) (0x80 | (codePoint & 0x3F));
        } else if (codePoint < 0x10000) { // 3 bytes
            buffer[pos++] = (byte) (0xE0 | (codePoint >> 12));
            buffer[pos++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
            buffer[pos++] = (byte) (0x80 | (codePoint & 0x3F));
        } else { // 4 bytes (surrogate pairs not handled explicitly)
            buffer[pos++] = (byte) (0xF0 | (codePoint >> 18));
            buffer[pos++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
            buffer[pos++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
            buffer[pos++] = (byte) (0x80 | (codePoint & 0x3F));
        }
    }
    // Assume LinkedBuffer has a write(byte[], int, int) method
    lb.write(buffer, 0, pos);
    return lb;
}

