public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String path = u.getPath();
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (path == null || path.isEmpty() || path.equals("/")) {
        return segments;
    }
    int start = 0;
    if (path.startsWith("/") && path.length() > 1) {
        start = 1; // ignore the leading slash for absolute paths
    }
    String sub = path.substring(start);
    for (String seg : sub.split("/", -1)) {
        String value = seg;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(seg, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(value));
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    // Remove leading '/' if present so it is not considered a delimiter
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    // Split the path into segments
    String[] parts = rawPath.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String decodedPart;
        try {
            decodedPart = decode ? java.net.URLDecoder.decode(part, "UTF-8") : part;
        } catch (java.io.UnsupportedEncodingException e) {
            // UTF-8 is guaranteed to be supported, so rethrow as unchecked
            throw new RuntimeException(e);
        }
        segments.add(new PathSegmentImpl(part, decodedPart));
    }
    return segments;
}

