public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String rawPath = u.getRawPath(); // raw path preserves encoded form
    if (rawPath == null || rawPath.isEmpty()) {
        return new ArrayList<>();
    }
    // split on '/' but ignore leading slash for absolute paths
    String[] split = rawPath.split("/");
    List<PathSegmentImpl> segments = new ArrayList<>();
    for (String seg : split) {
        // skip an empty segment that results from a leading '/'
        if (seg.isEmpty() && rawPath.startsWith("/") && segments.isEmpty()) {
            continue;
        }
        String decoded = seg;
        if (decode) {
            try {
                decoded = java.net.URLDecoder.decode(seg, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        // Assuming PathSegmentImpl has a constructor that accepts encoded and decoded forms
        segments.add(new PathSegmentImpl(seg, decoded));
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> result = new ArrayList<>();
    if (u == null) {
        return result;
    }
    String path = u.getRawPath();
    if (path == null || path.isEmpty()) {
        return result;
    }
    int pos = 0;
    // Ignore leading '/' if path is absolute
    if (path.startsWith("/") && u.isAbsolute()) {
        pos = 1;
    }
    while (pos >= 0 && pos < path.length()) {
        int next = path.indexOf('/', pos);
        String seg;
        if (next == -1) {
            seg = path.substring(pos);
            pos = -1; // end loop
        } else {
            seg = path.substring(pos, next);
            pos = next + 1;
        }
        if (decode) {
            try {
                seg = URLDecoder.decode(seg, StandardCharsets.UTF_8.name());
            } catch (UnsupportedEncodingException ex) {
                throw new RuntimeException(ex);
            }
        }
        result.add(new PathSegmentImpl(seg, !decode));
    }
    return result;
}

