public long readRawVarint64() throws IOException {
    long result = 0L;
    int shift = 0;
    while (true) {
        int b = this.read();
        if (b == -1) {
            throw new EOFException();
        }
        result |= (long)(b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
        if (shift >= 64) {
            throw new IOException("Malformed Varint");
        }
    }
}

public long readRawVarint64() throws IOException {
