        }
        result |= (long)(b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
        if (shift >= 64) {
            // Varint overrun, throw if more than 10 bytes read
            for (int i = 0; i < 3; i++) {
                int tmp = in.read();
                if (tmp == -1) {
                    throw new EOFException();
                }
                if ((tmp & 0x80) == 0) {
                    return result;
                }
            }
            throw new IOException("Varint too long");
        }
    }
}

