private void pop(final String descriptor){
    int p = descriptor.indexOf('(');
    if (p >= 0) { // method descriptor
        int end = descriptor.indexOf(')', p);
        if (end < 0) {
            return; // malformed descriptor
        }
        String types = descriptor.substring(p + 1, end);
        int i = 0;
        while (i < types.length()) {
            char c = types.charAt(i);
            if (c == 'L') { // reference type
                int semicolon = types.indexOf(';', i);
                if (semicolon < 0) {
                    return; // malformed
                }
                i = semicolon + 1;
                --pos;
            } else if (c == '[') { // array type
                i++;
                while (i < types.length() && types.charAt(i) == '[') {
                    i++;
                }
                if (i < types.length()) {
                    if (types.charAt(i) == 'L') {
                        int semicolon = types.indexOf(';', i);
                        if (semicolon < 0) {
                            return; // malformed
                        }
                        i = semicolon + 1;
                    } else {
                        i++;
                    }
                }
                --pos;
            } else { // primitive
                i++;
                --pos;
            }
        }
    } else { // single type descriptor
        int i = 0;
        while (i < descriptor.length()) {
            char c = descriptor.charAt(i);
            if (c == 'L') {
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon < 0) {
                    return; // malformed
                }
                i = semicolon + 1;
                --pos;
            } else if (c == '[') {
                i++;
                while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                    i++;
                }
                if (i < descriptor.length()) {
                    if (descriptor.charAt(i) == 'L') {
                        int semicolon = descriptor.indexOf(';', i);
                        if (semicolon < 0) {
                            return; // malformed
                        }
                        i = semicolon + 1;
                    } else {
                        i++;
                    }
                }
                --pos;
            } else { // primitive
                i++;
                --pos;
            }
        }
    }
}

private void pop(final String descriptor){
    if (descriptor.charAt(0) == '('){
        int p = 1;
        while (descriptor.charAt(p) != ')'){
            char c = descriptor.charAt(p);
            if (c == '['){
                while (descriptor.charAt(p) == '['){ p++; }
                // after array base type
                c = descriptor.charAt(p);
            }
            if (c == 'L'){
                p = descriptor.indexOf(';', p) + 1;
                pos--;
            } else {
                if (c == 'J' || c == 'D'){
                    pos -= 2;
                } else {
                    pos--;
                }
                p++;
            }
        }
    } else {
        int p = 0;
        char c = descriptor.charAt(p);
        if (c == '['){
            while (descriptor.charAt(p) == '['){ p++; }
            // array type consumes one slot
            pos--;
        } else {
            if (c == 'J' || c == 'D'){
                pos -= 2;
            } else {
                pos--;
            }
        }
    }
}

private void pop(final String descriptor){
    int i = 0;
    while (i < descriptor.length()){
        char c = descriptor.charAt(i);
        if (c == '('){                      // method descriptor
            i++;                            // skip '('
            while (i < descriptor.length() && descriptor.charAt(i) != ')'){
                c = descriptor.charAt(i);
                switch (c) {
                    case 'B': case 'S': case 'I':
                    case 'C': case 'Z': case 'F':
                    case 'D': case 'J':
                        i++;
                        stack[--pos];           // pop primitive
                        break;
                    case 'L':
                        i++;
                        while (descriptor.charAt(i) != ';') { i++; }
                        i++;                         // skip ';'
                        stack[--pos];           // pop object
                        break;
                    case '[':
                        do { i++; } while (descriptor.charAt(i) == '['); // skip array dims
                        if (descriptor.charAt(i) == 'L'){
                            i++;
                            while (descriptor.charAt(i) != ';') { i++; }
                            i++;                         // skip ';'
                        } else {
                            i++;                         // primitive base
                        }
                        stack[--pos];               // pop array
                        break;
                    default:
                        throw new IllegalArgumentException("Unknown descriptor char: " + c);
                }
            }
            i++;                                // skip ')'
            // ignore return type (if any)
            break;
        } else {                                // single type descriptor
            switch (c) {
                case 'B': case 'S': case 'I':
                case 'C': case 'Z': case 'F':
                case 'D': case 'J':
                    i++;
                    stack[--pos];
                    break;
                case 'L':
                    i++;
                    while (descriptor.charAt(i) != ';') { i++; }
                    i++;
                    stack[--pos];
                    break;
                case '[':
                    do { i++; } while (descriptor.charAt(i) == '[');
                    if (descriptor.charAt(i) == 'L'){
                        i++;
                        while (descriptor.charAt(i) != ';') { i++; }
                        i++;
                    } else {
                        i++;
                    }
                    stack[--pos];
                    break;
                default:
                    throw new IllegalArgumentException("Unknown descriptor char: " + c);
            }
        }
    }
}

private void pop(final String descriptor){
    // If the descriptor is a method descriptor, parse the argument types and pop one stack entry per argument
    if (descriptor.charAt(0) == '('){
        int end = descriptor.indexOf(')');
        String args = descriptor.substring(1, end);
        int i = 0;
        while (i < args.length()){
            char c = args.charAt(i);
            // Skip array prefixes
            if (c == '['){
                i++;
                continue;
            }
            // Object type – consumes until ';'
            if (c == 'L'){
                int semicolon = args.indexOf(';', i);
                pos--;                       // pop one entry for the object reference
                i = semicolon + 1;
                continue;
            }
            // Primitive type – consumes one character
            pos--;                           // pop one entry for the primitive
            i++;
        }
    } else {
        // Single type descriptor – pop one stack entry
        if (descriptor.charAt(0) == 'L'){
            pos--;                       // object type
        } else {
            pos--;                       // primitive type
        }
    }
}

private void pop(final String descriptor){
    int slots = 0;
    String args;
    if (descriptor.charAt(0) == '('){
        int end = descriptor.indexOf(')', 0);
        args = descriptor.substring(1, end);
    } else {
        args = descriptor;
    }
    final int len = args.length();
    for (int i = 0; i < len; i++){
        char c = args.charAt(i);
        switch (c){
            case '[':
                i++;
                while (i < len && args.charAt(i) == '['){
                    i++;
                }
                if (i < len && args.charAt(i) == 'L'){
                    i = args.indexOf(';', i);
                }
                slots++;
                break;
            case 'L':
                i = args.indexOf(';', i);
                slots++;
                break;
            case 'J':
            case 'D':
                slots += 2;
                break;
            default:
                slots++;
                break;
        }
    }
    pos -= slots;
}

