public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int total = 0;
    if (node == null) {
        return 0;
    }
    try {
        java.lang.Class<?> cls = node.getClass();
        java.lang.reflect.Field bufferField = null;
        java.lang.reflect.Field sizeField = null;
        java.lang.reflect.Field nextField = null;
        // try to find the field that holds the byte array
        try {
            bufferField = cls.getDeclaredField("buffer");
        } catch (NoSuchFieldException e) {
            try {
                bufferField = cls.getDeclaredField("buf");
            } catch (NoSuchFieldException ee) {
                bufferField = null;
            }
        }
        // try to find the field that holds the number of valid bytes
        try {
            sizeField = cls.getDeclaredField("size");
        } catch (NoSuchFieldException e) {
            try {
                sizeField = cls.getDeclaredField("len");
            } catch (NoSuchFieldException ee) {
                try {
                    sizeField = cls.getDeclaredField("length");
                } catch (NoSuchFieldException eee) {
                    sizeField = null;
                }
            }
        }
        // try to find the field that points to the next node
        try {
            nextField = cls.getDeclaredField("next");
        } catch (NoSuchFieldException e) {
            try {
                nextField = cls.getDeclaredField("nextBuffer");
            } catch (NoSuchFieldException ee) {
                try {
                    nextField = cls.getDeclaredField("nextNode");
                } catch (NoSuchFieldException eee) {
                    nextField = null;
                }
            }
        }
        if (bufferField == null || sizeField == null || nextField == null) {
            throw new IOException("Unable to access LinkedBuffer fields");
        }
        bufferField.setAccessible(true);
        sizeField.setAccessible(true);
        nextField.setAccessible(true);
        LinkedBuffer cur = node;
        while (cur != null) {
            byte[] buf = (byte[]) bufferField.get(cur);
            int len = sizeField.getInt(cur);
            if (len > 0 && buf != null) {
                out.write(buf, 0, len);
                total += len;
            }
            cur = (LinkedBuffer) nextField.get(cur);
        }
    } catch (Exception e) {
        throw new IOException(e);
    }
    return total;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int total = 0;
    for (LinkedBuffer cur = node; cur != null; cur = cur.next) {
        int len = cur.write - cur.read;
        if (len > 0) {
            out.write(cur.buf, cur.read, len);
            total += len;
        }
    }
    return total;
}

