int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }
    int n = desiredCapacity;
    // make sure we start on an odd number
    if ((n & 1) == 0) {
        n++;
    }
    while (n <= Integer.MAX_VALUE - 10) {
        if (isPrime(n)) {
            return n;
        }
        // if desiredCapacity is large, limit growth to within 11%
        if (desiredCapacity >= 1000) {
            int maxAllowed = (int) Math.floor(desiredCapacity * 1.11);
            if (n > maxAllowed) {
                // fallback to nearest prime after the bound
                while (!isPrime(n)) {
                    n += 2;
                }
                return n;
            }
        }
        n += 2;
    }
    return Integer.MAX_VALUE;
}

private static boolean isPrime(int n) {
    if (n <= 3) {
        return n > 1;
    }
    if ((n & 1) == 0 || n % 3 == 0) {
        return false;
    }
    for (long i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

