@Override public String readString() throws IOException {
    int len = readInt();
    if (len < 0) {
        return null;
    }
    byte[] buf = new byte[len];
    int read = 0;
    while (read < len) {
        int r = in.read(buf, read, len - read);
        if (r == -1) {
            throw new EOFException("Unexpected end of stream while reading string");
        }
        read += r;
    }
    return new String(buf, "UTF-8");
}

