@Override public String readString() throws IOException {
    // Read a two-byte length prefix (big-endian) first
    byte[] lenBuf = new byte[2];
    int n = in.read(lenBuf);
    if (n != 2) {
        throw new EOFException("Cannot read string length");
    }
    int len = ((lenBuf[0] & 0xFF) << 8) | (lenBuf[1] & 0xFF);
    // Now read exactly `len` bytes
    byte[] data = new byte[len];
    int readTotal = 0;
    while (readTotal < len) {
        int read = in.read(data, readTotal, len - readTotal);
        if (read == -1) {
            throw new EOFException("Unexpected end of stream while reading string");
        }
        readTotal += read;
    }
    // Assume UTF-8 encoding for the string
    return new String(data, StandardCharsets.UTF_8);
}

