public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder result = new StringBuilder(str.length());
    int i = 0;
    while (i < str.length()) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < str.length()) {
            char next = str.charAt(i + 1);
            switch (next) {
                case 'n':
                    result.append('\n');
                    break;
                case 't':
                    result.append('\t');
                    break;
                case 'r':
                    result.append('\r');
                    break;
                case 'b':
                    result.append('\b');
                    break;
                case 'f':
                    result.append('\f');
                    break;
                case '\\':
                    result.append('\\');
                    break;
                case '\'':
                    result.append('\'');
                    break;
                case '\"':
                    result.append('\"');
                    break;
                default:
                    // If the escape sequence is not recognized, keep the literal character
                    result.append(next);
                    break;
            }
            i += 2; // skip the escape sequence
        } else {
            result.append(c);
            i++;
        }
    }
    return result.toString();
}

