protected int removeUnusedNodes(){
    if (root == null) {
        return 0;
    }
    int removedCount = 0;
    Deque<Category> stack = new ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        Category current = stack.pop();
        List<Category> children = current.getChildren();
        if (children != null) {
            Iterator<Category> it = children.iterator();
            while (it.hasNext()) {
                Category child = it.next();
                stack.push(child);
                if (!child.isActive()) {
                    it.remove();
                    removedCount++;
                }
            }
        }
    }
    // Optionally remove the root node if it is inactive
    if (!root.isActive()) {
        root = null;
        removedCount++;
    }
    return removedCount;
}

int function() { 
