        return 0; 
    } 
    int removedCount = 0; 
    java.util.Deque<Category> stack = new java.util.ArrayDeque<>(); 
    stack.push(root); 
    while (!stack.isEmpty()) { 
        Category current = stack.pop(); 
        java.util.List<Category> children = current.getChildren(); 
        if (children == null) { 
            continue; 
        } 
        for (int i = children.size() - 1; i >= 0; i--) { 
            Category child = children.get(i); 
            stack.push(child); 
            if (!child.isActive()) { 
                children.remove(i); 
                removedCount++; 
            } 
        } 
    } 
    if (!root.isActive()) { 
        root = null; 
        removedCount++; 
    } 
    return removedCount; 
}

