private int prune(Category parent){ 
    int removed = 0;
    List<Category> children = new ArrayList<>(parent.getChildren());
    for (Category child : children){
        if (!child.isActive()){
            parent.removeChild(child);
            removed++;
        } else {
            removed += prune(child);
        }
    }
    return removed;
}

