    int offset = this.constantPoolEntryOffsets[constantPoolEntryIndex];
    int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    java.nio.ByteBuffer byteBuf = java.nio.ByteBuffer.wrap(classFileBuffer, offset + 2, length);
    java.nio.CharBuffer charBuf = java.nio.charset.StandardCharsets.UTF_8.decode(byteBuf);
    int charsRead = charBuf.remaining();
    charBuf.get(charBuffer, 0, charsRead);
    return new String(charBuffer, 0, charsRead);
