private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    Node current = start;
    // Traverse in the specified direction until we hit the stop node
    // or find a node that satisfies the predicate.
    while (true) {
        // If the current node satisfies the predicate, return it.
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }
        // If we have reached the stop node, return it (even if it doesn't satisfy the predicate).
        if (current == stop) {
            return new OuterFaceCirculator(stop);
        }
        // Move to the next node in the given direction.  
        // Assumes Node provides a method to get the next node along the outer face 
        // in the provided direction (e.g., getNextOuterFace(int dir)).
        current = current.getNextOuterFace(dir);
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    Node current = start;
    while (!current.equals(stop) && !predicate.test(current)) {
        current = (dir >= 0) ? current.getOuterRight() : current.getOuterLeft();
    }
    return new OuterFaceCirculator(current, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (start == null) {
        return null;
    }
    OuterFaceCirculator circ = new OuterFaceCirculator(start);
    if (predicate.test(circ.node())) {
        return circ;
    }
    while (true) {
        circ.move(dir);
        Node current = circ.node();
        if (current == stop) {
            return circ;
        }
        if (predicate.test(current)) {
            return circ;
        }
        if (current == start) { // completed a full loop without finding predicate or stop
            break;
        }
    }
    // If we exit the loop, return a circulator positioned at the stop node
    return new OuterFaceCirculator(stop);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    while (!circ.current().equals(stop)) {
        if (predicate.test(circ.current())) {
            break;
        }
        circ.next();
    }
    return circ;
}

