        "sse".equalsIgnoreCase(r.getTransportName())) {
        r.suspend();
    }
    return Action.CONTINUE;
}

@Override public Action inspect(AtmosphereResource r){
    if (r == null) {
        return Action.CONTINUE;
    }
    AtmosphereResource.TRANSPORT transport = r.getTransport();
    if (transport != AtmosphereResource.TRANSPORT.WEBSOCKET) {
        r.suspend();
    }
    return Action.CONTINUE;
}

@Override public Action inspect(AtmosphereResource r){
    if (r == null) {
        return Action.CONTINUE;
    }
    String transport = r.getTransport();
    if (transport == null) {
        return Action.CONTINUE;
    }
    // Suspend based on the transport type
    if (AtmosphereResource.TRANSPORT.WEBSOCKET.equals(transport)) {
        // WebSocket transports are typically long-lived – suspend immediately
        r.suspend();
    } else if (AtmosphereResource.TRANSPORT.HTTP.equals(transport)
            || AtmosphereResource.TRANSPORT.LONG_POLLING.equals(transport)) {
        // For HTTP based transports use a timeout (example: 30 seconds)
        r.suspend(30 * 1000L);
    } else {
        // Default behaviour – suspend without timeout
        r.suspend();
    }
    return Action.CONTINUE;
}

@Override public Action inspect(AtmosphereResource r){
    String transport = r.getTransport();
    if ("websocket".equalsIgnoreCase(transport) || "ws".equalsIgnoreCase(transport)) {
        r.suspend();
    }
    return Action.CONTINUE;
}

@Override public Action inspect(AtmosphereResource r){
    if (AtmosphereResource.TRANSPORT.WEBSOCKET.equals(r.getTransport()) && !r.isSuspended()){
        r.suspend();
    }
    return Action.CONTINUE;
}

