protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty()){
        return null;
    }
    // Build adjacency map
    Map<V, List<E>> adj = new HashMap<>();
    for (E e : tour){
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adj.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
        if (!graph.getType().isDirected()){
            adj.computeIfAbsent(tgt, k -> new ArrayList<>()).add(e);
        }
    }
    // Find a start vertex
    V start = null;
    for (V v : graph.vertexSet()){
        if (adj.containsKey(v)){
            start = v;
            break;
        }
    }
    if (start == null){
        return null;
    }
    List<E> edgeList = new ArrayList<>();
    List<V> vertexList = new ArrayList<>();
    Set<E> visited = new HashSet<>();
    V curr = start;
    vertexList.add(curr);
    while (visited.size() < tour.size()){
        List<E> edges = adj.get(curr);
        if (edges == null){
            break;
        }
        E chosen = null;
        for (E e : edges){
            if (!visited.contains(e)){
                chosen = e;
                break;
            }
        }
        if (chosen == null){
            break;
        }
        edgeList.add(chosen);
        visited.add(chosen);
        V src = graph.getEdgeSource(chosen);
        V tgt = graph.getEdgeTarget(chosen);
        V next = src.equals(curr) ? tgt : src;
        vertexList.add(next);
        curr = next;
    }
    double weight = 0.0;
    for (E e : edgeList){
        weight += graph.getEdgeWeight(e);
    }
    return new org.jgrapht.graph.BaseGraphPath<>(graph, start, vertexList, edgeList, weight);
}

