protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty()) {
        return null;
    }
    // Map each vertex to its outgoing edge in the tour
    Map<V, E> outMap = new HashMap<>();
    Map<V, E> inMap = new HashMap<>();
    for (E e : tour) {
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        outMap.put(u, e);
        inMap.put(v, e);
    }
    // Choose a start vertex: one that has an outgoing edge but no incoming edge
    V start = null;
    for (V v : graph.vertexSet()) {
        if (outMap.containsKey(v) && !inMap.containsKey(v)) {
            start = v;
            break;
        }
    }
    // If no such vertex (e.g., a cycle), pick an arbitrary one
    if (start == null) {
        start = outMap.keySet().iterator().next();
    }
    // Build the ordered edge list
    List<E> edgeList = new ArrayList<>();
    Set<E> visited = new HashSet<>();
    V current = start;
    while (true) {
        E e = outMap.get(current);
        if (e == null) {
            break;
        }
        if (!visited.add(e)) {
            // Already visited this edge – finished the tour
            break;
        }
        edgeList.add(e);
        current = graph.getEdgeTarget(e);
    }
    // Calculate total weight of the path
    double totalWeight = 0.0;
    for (E e : edgeList) {
        totalWeight += graph.getEdgeWeight(e);
    }
    // Return a new GraphPath instance (using GraphPathImpl)
    return new GraphPathImpl<>(graph, start, current, totalWeight, edgeList);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Edge case: empty tour
    if (tour == null || tour.isEmpty()) {
        return new GraphPathImpl<V, E>(graph, null, null, new ArrayList<V>(), new ArrayList<E>(), 0.0);
    }
    // Use a LinkedHashSet to preserve order for deterministic behavior
    Set<E> remaining = new LinkedHashSet<E>(tour);
    // Start with an arbitrary edge
    Iterator<E> iter = remaining.iterator();
    E startEdge = iter.next();
    V startVertex = graph.getEdgeSource(startEdge);
    V current = graph.getEdgeTarget(startEdge);
    List<V> vertexList = new ArrayList<V>();
    List<E> edgeList = new ArrayList<E>();
    vertexList.add(startVertex);
    vertexList.add(current);
    edgeList.add(startEdge);
    remaining.remove(startEdge);
    // Build the tour cycle
    while (!remaining.isEmpty()) {
        E nextEdge = null;
        for (E e : remaining) {
            V source = graph.getEdgeSource(e);
            V target = graph.getEdgeTarget(e);
            if (source.equals(current)) {
                nextEdge = e;
                current = target;
                break;
            } else if (target.equals(current)) {
                nextEdge = e;
                current = source;
                break;
            }
        }
        if (nextEdge == null) {
            // The remaining edges do not connect to the current vertex; abort
            break;
        }
        vertexList.add(current);
        edgeList.add(nextEdge);
        remaining.remove(nextEdge);
    }
    // In a valid tour, current should equal startVertex. If not, the input may be invalid.
    V endVertex = vertexList.isEmpty() ? null : vertexList.get(vertexList.size() - 1);
    return new GraphPathImpl<V, E>(graph, startVertex, endVertex, vertexList, edgeList, 0.0);
}

