int addConstantNameAndType(final String name,final String descriptor){
    int nameIdx = findUtf8(name);
    int descriptorIdx = findUtf8(descriptor);
    if (nameIdx == NOT_FOUND || descriptorIdx == NOT_FOUND) {
        return -1;
    }
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == NAME_TYPE) {
            int nIdx = readInt(i);
            int dIdx = readInt(i + 1);
            if (nIdx == nameIdx && dIdx == descriptorIdx) {
                return i;
            }
        }
    }
    return -1;
}

