int addConstantNameAndType(final String name, final String descriptor) {
    // Construct a unique key for the (name, descriptor) pair
    final String key = name + '\0' + descriptor;
    Integer existing = _nameAndTypeMap.get(key);
    if (existing != null) {
        return existing;
    }

    // Add the name and descriptor to the constant pool if not already present
    int nameIndex = addConstantUtf8(name);
    int descriptorIndex = addConstantUtf8(descriptor);

    // Create the new CONSTANT_NameAndType_info entry
    ConstantNameAndTypeInfo info = new ConstantNameAndTypeInfo(nameIndex, descriptorIndex);
    _pool.add(info);
    int newIndex = _pool.size() - 1;

    // Remember the new entry so next call with same name/descriptor returns it
    _nameAndTypeMap.put(key, newIndex);
    return newIndex;
}

int addConstantNameAndType(final String name,final String descriptor){
    int nameIdx = findUtf8(name);
    if(nameIdx == NOT_FOUND){
        nameIdx = addUtf8(name);
    }
    int descIdx = findUtf8(descriptor);
    if(descIdx == NOT_FOUND){
        descIdx = addUtf8(descriptor);
    }
    int loc = findNameAndType(name, descriptor);
    if(loc == NOT_FOUND){
        int idx = endOfPool;
        // extend types array
        types = java.util.Arrays.copyOf(types, idx+1);
        // extend byteCode array to hold two u2 indices
        int bcPos = byteCode.length;
        byteCode = java.util.Arrays.copyOf(byteCode, bcPos+4);
        byteCode[bcPos]     = (byte)(nameIdx>>>8);
        byteCode[bcPos+1]   = (byte)(nameIdx & 0xFF);
        byteCode[bcPos+2]   = (byte)(descIdx>>>8);
        byteCode[bcPos+3]   = (byte)(descIdx & 0xFF);
        // extend offsets array and record offset
        offsets = java.util.Arrays.copyOf(offsets, idx+1);
        offsets[idx] = bcPos;
        types[idx] = NAME_TYPE; // constant tag for NameAndType
        endOfPool++;
        loc = idx;
    }
    return loc;
}

int addConstantNameAndType(final String name,final String descriptor){
    /* Search for an existing CONSTANT_NameAndType_info that matches the given name and descriptor */
    int nameIdx = getUtf8Index(name);
    int descIdx = getUtf8Index(descriptor);
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == NAMEANDTYPE && nameIndices[i] == nameIdx && descriptorIndices[i] == descIdx) {
            return i; /* Return the index of the existing entry */
        }
    }
    /* No matching entry found – create a new one */
    int newIndex = endOfPool;
    types[newIndex] = NAMEANDTYPE;
    nameIndices[newIndex] = nameIdx;
    descriptorIndices[newIndex] = descIdx;
    endOfPool++;
    return newIndex;
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < len) {
            sb.append(input.charAt(i + 1));
            i++;
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

private String unescapeId(String input){
    if (input == null || input.isEmpty()){
        return input;
    }
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++){
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < len){
            char next = input.charAt(i + 1);
            if (next == 'u' && i + 5 < len){
                // Unicode escape \uXXXX
                String hex = input.substring(i + 2, i + 6);
                try{
                    int code = Integer.parseInt(hex, 16);
                    sb.append((char) code);
                    i += 5; // skip \uXXXX
                    continue;
                }catch (NumberFormatException e){
                    // fall through to normal handling
                }
            }
            // For other escapes, just append the escaped character
            sb.append(next);
            i++; // skip the escape character
        }else{
            sb.append(c);
        }
    }
    return sb.toString();
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    int i = 0;
    // If wrapped in double quotes, skip them
    if (len >= 2 && input.charAt(0) == '"' && input.charAt(len - 1) == '"') {
        i = 1;
        len--; // exclude the closing quote
    }
    while (i < len) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = input.charAt(i + 1);
            i++; // skip the escape character
            switch (next) {
                case 'n':
                    sb.append('\n');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'v':
                    sb.append('\u000B'); // vertical tab
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                default:
                    // For any other escaped character, keep it as is
                    sb.append(next);
                    break;
            }
        } else {
            sb.append(c);
        }
        i++;
    }
    return sb.toString();
}

