private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    if (minBucket == null || minBucket.isEmpty()) {
        return;
    }
    for (Integer vertex : minBucket) {
        zeroBucket.add(vertex);
        labels.set(vertex, 0);
    }
    minBucket.clear();
}

private void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel){
    // Obtain the bucket for the minimum label and the bucket for label 0
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    if (zeroBucket == null) {
        zeroBucket = new HashSet<>();
        bucketsByLabel.set(0, zeroBucket);
    }
    // If the min bucket exists and is non-empty, move all its vertices to bucket 0
    if (minBucket != null && !minBucket.isEmpty()) {
        for (Integer vertex : minBucket) {
            zeroBucket.add(vertex);          // add to bucket 0
            labels.set(vertex, 0);           // update vertex label to 0
        }
        minBucket.clear();                    // clear the min bucket after moving
    }
}

private void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel){
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()){
        return;
    }
    Set<Integer> target = bucketsByLabel.get(0);
    if (target == null){
        target = new HashSet<>();
        bucketsByLabel.set(0, target);
    }
    for (Integer v : new ArrayList<>(source)) {
        target.add(v);
        labels.set(v, 0);
    }
    source.clear();
}

void function ( List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel ) { 
    Set<Integer> source = bucketsByLabel.get(minLabel); 
    if (source == null || source.isEmpty()) { 
        return; 
    } 
    // Update labels for vertices that are moved to bucket 0 
    for (Integer vertex : source) { 
        labels.set(vertex, 0); 
    } 
    // Move vertices to bucket 0 
    Set<Integer> target = bucketsByLabel.get(0); 
    if (target == null) { 
        target = new HashSet<>(); 
        bucketsByLabel.set(0, target); 
    } 
    target.addAll(source); 
    // Clear the original bucket 
    source.clear(); 
}

private void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel){
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    if (minBucket != null && !minBucket.isEmpty()){
        for (Integer v : minBucket){
            labels.set(v, 0);
        }
        zeroBucket.addAll(minBucket);
        minBucket.clear();
    }
}

