private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    long total = 0L;
    for (Integer v : bounds) {
        total += v;
    }
    int size = bounds.size();
    int[] tmp = new int[size];
    long running = 0L;
    for (int i = size - 1; i >= 0; i--) {
        running += bounds.get(i);
        tmp[i] = (int) running;
    }
    List<Integer> suffix = new ArrayList<>(size);
    for (int i = 0; i < size; i++) {
        suffix.add(tmp[i]);
    }
    return new Pair<>(suffix, total);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long total = 0;
    long[] temp = new long[n];
    for(int i=n-1;i>=0;i--){
        total += bounds.get(i);
        temp[i] = total;
    }
    for(long val : temp){
        suffix.add((int)val);
    }
    return Pair.of(suffix, total);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if(bounds == null || bounds.isEmpty()){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    List<Integer> suffix = new ArrayList<>(bounds.size());
    long total = 0L;
    int suffixSum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        int value = bounds.get(i);
        total += value;
        suffixSum += value;
        suffix.add(0, suffixSum);
    }
    return new Pair<>(suffix, total);
}

