    int[] suffix = new int[n];
    int running = 0;
    for (int i = n - 1; i >= 0; i--) {
        running += bounds.get(i);
        suffix[i] = running;
    }
    for (int i = 0; i < n; i++) {
        suffixSums.add(suffix[i]);
    }
    long total = 0L;
    for (int val : bounds) {
        total += val;
    }
    return new Pair<>(suffixSums, total);
}

