    }
    return new Pair<>(suffix, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    while (from < to) {
        V temp = arr[from];
        arr[from++] = arr[to];
        arr[to--] = temp;
    }
}

public static final <V> void reverse(V[] arr,int from,int to){
    int i = from, j = to;
    while(i < j){
        V tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null || list.size == 0) {
        return;
    }
    ListNodeImpl<E> first = list.head;
    ListNodeImpl<E> last = list.tail;
    if (this.head == null) {
        this.head = first;
    } else {
        this.tail.next = first;
        first.prev = this.tail;
    }
    this.tail = last;
    this.size += list.size;
    list.head = null;
    list.tail = null;
    list.size = 0;
}

