    // If the destination list is empty, just take over the nodes.
    if (this.size == 0) {
        this.first = list.first;
        this.last  = list.last;
    } else {
        // Link the tail of this list to the head of the source list
        this.last.next = list.first;
        list.first.prev = this.last;
        this.last = list.last;
    }
    // Update the size of the destination list
    this.size += list.size;
    // Reset the source list to an empty state.
    list.first = null;
    list.last  = null;
    list.size  = 0;
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    // Continuously detach the first node of the source list and append it to this list
    while (list.head != null) {
        // Grab the first node from the source list
        ListNodeImpl<E> srcNode = list.head;

        // Update the source list's head pointer
        list.head = srcNode.next;
        if (srcNode.next != null) {
            srcNode.next.prev = null; // detach forward link
        } else {
            // Source list is now empty; clear its tail
            list.tail = null;
        }

        // Decrease the source list's element count
        list.size--;

        // Attach the node to the end of this list
        srcNode.prev = this.tail;
        srcNode.next = null;
        if (this.tail != null) {
            this.tail.next = srcNode;
        } else {
            // This list was empty; set its head too
            this.head = srcNode;
        }
        this.tail = srcNode;
        this.size++;
    }
}

