public void abbreviate(final int nameStart,final StringBuffer buf){
    String fullName = this.name; // assume a field holding the full name
    if (fullName == null || nameStart < 0 || nameStart >= fullName.length()) {
        return;
    }
    int pos = nameStart;
    // Append first non-space character after nameStart
    while (pos < fullName.length() && Character.isWhitespace(fullName.charAt(pos))) {
        pos++;
    }
    if (pos < fullName.length()) {
        buf.append(fullName.charAt(pos));
    }
    // Append first character after each space
    while (pos < fullName.length()) {
        if (Character.isWhitespace(fullName.charAt(pos))) {
            int next = pos + 1;
            while (next < fullName.length() && Character.isWhitespace(fullName.charAt(next))) {
                next++;
            }
            if (next < fullName.length()) {
                buf.append(fullName.charAt(next));
                pos = next;
            } else {
                break;
            }
        } else {
            pos++;
        }
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    String name = this.name;                     // assume a field holding the full name
    int len = name.length();
    int i = nameStart;
    while (i < len) {
        // Skip any whitespace before a word
        while (i < len && Character.isWhitespace(name.charAt(i))) i++;
        if (i >= len) break;
        // Append the first character of the current word
        buf.append(name.charAt(i));
        i++;
        // Skip the rest of the current word
        while (i < len && !Character.isWhitespace(name.charAt(i))) i++;
        // Determine if more words remain; if so, add a separator
        int j = i;
        while (j < len && Character.isWhitespace(name.charAt(j))) j++;
        if (j < len) {
            buf.append('.');
        }
    }
}

