        result.add(lb);
    }
    return result;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    TreeSet<K> set = new TreeSet<>(keys);
    for (K key : keys) {
        K lower = set.lower(key);
        if (lower != null) {
            bounds.add((Integer) lower);
        } else {
            bounds.add(Integer.MIN_VALUE);
        }
    }
    return bounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    for (int i = 0; i < keys.size(); i++) {
        Integer maxLower = null;
        for (int j = 0; j < keys.size(); j++) {
            if (i == j) continue;
            @SuppressWarnings("unchecked")
            K other = keys.get(j);
            @SuppressWarnings("unchecked")
            K current = keys.get(i);
            @SuppressWarnings("unchecked")
            Comparable<K> cmpCurrent = (Comparable<K>) current;
            if (cmpCurrent.compareTo(other) < 0) {
                Integer val = (Integer) other;
                if (maxLower == null || val > maxLower) {
                    maxLower = val;
                }
            }
        }
        bounds.add(maxLower);
    }
    return bounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> result = new ArrayList<>(keys.size());
    List<Integer> sorted = new ArrayList<>(keys.size());
    for (K k : keys) {
        sorted.add((Integer) k);
    }
    Collections.sort(sorted);
    for (K k : keys) {
        int val = (Integer) k;
        int index = Collections.binarySearch(sorted, val);
        if (index < 0) {
            index = -index - 1;
        }
        int bound = (index > 0) ? sorted.get(index - 1) : Integer.MIN_VALUE;
        result.add(bound);
    }
    return result;
}

private void pop(final String descriptor) {
    int slots = 0;
    int idx = 0;
    // method descriptor
    if (descriptor.charAt(0) == '(') {
        idx = 1;
        while (idx < descriptor.length() && descriptor.charAt(idx) != ')') {
            char c = descriptor.charAt(idx);
            // skip array brackets
            while (c == '[') {
                idx++;
                c = descriptor.charAt(idx);
            }
            if (c == 'L') {
                // reference type
                slots++;
                idx++; // skip 'L'
                while (idx < descriptor.length() && descriptor.charAt(idx) != ';') {
                    idx++;
                }
                idx++; // skip ';'
            } else {
                // primitive type
                if (c == 'J' || c == 'D') {
                    slots += 2;
                } else {
                    slots += 1;
                }
                idx++;
            }
        }
    } else {
        // single type descriptor
        char c = descriptor.charAt(0);
        if (c == '[') {
            // array type – always 1 slot
            slots = 1;
        } else if (c == 'L') {
            slots = 1;
        } else {
            slots = (c == 'J' || c == 'D') ? 2 : 1;
        }
    }
    // pop the calculated number of slots from the stack
    for (int i = 0; i < slots; i++) {
        stack[--pos] = null;
    }
}

private void pop(final String descriptor) {
    int start = descriptor.indexOf('(');
    if (start >= 0) {
        int end = descriptor.indexOf(')', start);
        int i = start + 1;
        while (i < end) {
            // skip array brackets
            while (i < end && descriptor.charAt(i) == '[') i++;
            if (i < end && descriptor.charAt(i) == 'L') {
                i++; // skip 'L'
                while (i < end && descriptor.charAt(i) != ';') i++;
                i++; // skip ';'
            } else {
                i++; // primitive type
            }
            pos--; // pop one type
        }
    } else {
        int i = 0;
        int len = descriptor.length();
        while (i < len) {
            while (i < len && descriptor.charAt(i) == '[') i++;
            if (i < len && descriptor.charAt(i) == 'L') {
                i++; // skip 'L'
                while (i < len && descriptor.charAt(i) != ';') i++;
                i++; // skip ';'
            } else {
                i++; // primitive type
            }
            pos--; // pop one type
        }
    }
}

private void pop(final String descriptor){
    int index = 0;
    if (descriptor.charAt(index) == '('){
        index++; // skip '('
        while (descriptor.charAt(index) != ')'){
            // Determine end of current argument type
            int start = index;
            char c = descriptor.charAt(start);
            // Skip any array dimensions
            while (c == '['){
                start++;
                c = descriptor.charAt(start);
            }
            if (c == 'L'){
                start++; // skip the 'L'
                while (descriptor.charAt(start) != ';'){
                    start++;
                }
                start++; // include the ';'
            } else {
                // primitive or void type
                start++; // single character
            }
            // Pop one element for the argument
            stack[--pos] = null;
            index = start;
        }
        // Skip closing ')'
        index++;
    } else {
        // Single type descriptor – pop one element
        stack[--pos] = null;
    }
}

private void pop(final String descriptor){
    int len = descriptor.length();
    if (len == 0) { return; }
    int idx = 0;
    if (descriptor.charAt(0) == '(') {
        idx = 1; // skip '('
        while (idx < len && descriptor.charAt(idx) != ')') {
            // skip array brackets
            while (descriptor.charAt(idx) == '[') {
                idx++;
            }
            // skip object type
            if (descriptor.charAt(idx) == 'L') {
                idx++;
                while (idx < len && descriptor.charAt(idx) != ';') {
                    idx++;
                }
                idx++; // skip ';'
            } else {
                // primitive descriptor: single char
                idx++;
            }
            // pop one element from the stack
            pos--;
        }
    } else {
        // single type descriptor, not a method
        // skip array brackets
        while (descriptor.charAt(idx) == '[') {
            idx++;
        }
        // skip object type
        if (descriptor.charAt(idx) == 'L') {
            idx++;
            while (idx < len && descriptor.charAt(idx) != ';') {
                idx++;
            }
            idx++; // skip ';'
        } else {
            // primitive descriptor: single char
            idx++;
        }
        pos--;
    }
}

