public static String applyRelativePath(String path,String relativePath){
    String[] baseParts = path.split("/");
    String[] relParts = relativePath.split("/");
    ArrayDeque<String> stack = new ArrayDeque<>();
    // Preserve leading slash if present
    if (path.startsWith("/")) {
        stack.addLast("");
    }
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().equals("")) {
                stack.removeLast();
            }
            continue;
        }
        stack.addLast(part);
    }
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().equals("")) {
                stack.removeLast();
            }
            continue;
        }
        stack.addLast(part);
    }
    StringBuilder sb = new StringBuilder();
    if (stack.isEmpty()) {
        sb.append(".");
    } else {
        Iterator<String> it = stack.iterator();
        while (it.hasNext()) {
            String seg = it.next();
            if (seg.isEmpty()) {
                sb.append("/");
            } else {
                if (sb.length() > 0 && sb.charAt(sb.length() - 1) != '/') {
                    sb.append("/");
                }
                sb.append(seg);
            }
        }
    }
    return sb.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        return null;
    }
    boolean isAbsolute = path.startsWith("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();

    // Process the base path
    String[] baseParts = path.split("/");
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().equals("..")) {
                stack.removeLast();
            } else if (!isAbsolute) {
                stack.addLast("..");
            }
        } else {
            stack.addLast(part);
        }
    }

    // Process the relative path
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().equals("..")) {
                stack.removeLast();
            } else if (!isAbsolute) {
                stack.addLast("..");
            }
        } else {
            stack.addLast(part);
        }
    }

    // Reconstruct the path
    StringBuilder sb = new StringBuilder();
    if (isAbsolute) {
        sb.append("/");
    }
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        sb.append(it.next());
        if (it.hasNext()) {
            sb.append("/");
        }
    }

    // Handle special cases
    if (sb.length() == 0) {
        return isAbsolute ? "/" : ".";
    }
    return sb.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        return path;
    }
    boolean pathStartsWithSlash = path.startsWith("/");
    boolean pathEndsWithSlash = path.endsWith("/");
    // Determine base segments (exclude file if path does not end with slash)
    String[] pathParts = path.split("/", -1); // preserve empty parts
    int baseEndIndex = pathParts.length;
    if (!pathEndsWithSlash && baseEndIndex > 0) {
        // Exclude the last part if it's not a directory separator
        baseEndIndex--;
    }
    java.util.List<String> stack = new java.util.ArrayList<>();
    for (int i = 0; i < baseEndIndex; i++) {
        if (!pathParts[i].isEmpty()) {
            stack.add(pathParts[i]);
        }
    }
    // Process relative path segments
    String[] relParts = relativePath.split("/", -1);
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }
    // Build the resulting path
    StringBuilder sb = new StringBuilder();
    if (pathStartsWithSlash) {
        sb.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        sb.append(stack.get(i));
        if (i < stack.size() - 1) {
            sb.append("/");
        }
    }
    // Handle case where stack is empty
    if (sb.length() == 0) {
        return pathStartsWithSlash ? "/" : ".";
    }
    return sb.toString();
}

public static String applyRelativePath(String path,String relativePath){
    // Split the base path into parts
    String[] pathParts = path.split("/");
    java.util.List<String> base = new java.util.ArrayList<String>();
    boolean endsWithSlash = path.endsWith("/");
    int lastIndex = pathParts.length - 1;
    int fileIndex = endsWithSlash ? lastIndex : lastIndex - 1;
    for(int i = 0; i <= fileIndex; i++){
        if (!pathParts[i].isEmpty()){
            base.add(pathParts[i]);
        }
    }
    // Preserve root slash
    if (path.startsWith("/")){
        base.add(0, "");
    }
    // Process the relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts){
        if (part.equals("") || part.equals(".")){
            continue;
        }
        if (part.equals("..")){
            if (base.size() > 1){
                base.remove(base.size() - 1);
            }
        } else {
            base.add(part);
        }
    }
    // Build the resulting path
    if (base.size() == 0){
        return "/";
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < base.size(); i++){
        if (i > 0){
            sb.append("/");
        }
        sb.append(base.get(i));
    }
    if (!sb.toString().startsWith("/")){
        sb.insert(0, "/");
    }
    return sb.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        return relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    // Split path into parts, preserving empty parts to keep leading slash
    String[] pathParts = path.split("/", -1);
    // Assume that the last part of the original path is a file name and remove it
    int baseEnd = pathParts.length - 1;
    java.util.List<String> result = new java.util.ArrayList<>();
    for (int i = 0; i < baseEnd; i++) {
        result.add(pathParts[i]);
    }
    // Process each segment of the relative path
    String[] relParts = relativePath.split("/");
    for (String seg : relParts) {
        if (seg.isEmpty() || seg.equals(".")) {
            continue; // skip empty or current-directory markers
        } else if (seg.equals("..")) {
            if (!result.isEmpty()) {
                // Avoid removing the root element represented by an empty string
                int removeIdx = result.size() - 1;
                if (result.get(removeIdx).isEmpty() && removeIdx == 0) {
                    // We're at root, cannot go up further
                    continue;
                }
                result.remove(removeIdx);
            }
        } else {
            result.add(seg);
        }
    }
    // Build the resolved path string
    java.lang.StringBuilder sb = new java.lang.StringBuilder();
    for (int i = 0; i < result.size(); i++) {
        if (i > 0) {
            sb.append("/");
        }
        sb.append(result.get(i));
    }
    // Handle the case where the result is empty (i.e., root)
    if (sb.length() == 0) {
        return ".";
    }
    return sb.toString();
}

