    Node prev = this._prevNode;
    Node next = this._nextNode;
    if(prev == null || next == null){
        return null;
    }
    Node realPrev = prev.isVirtual() ? prev.getRealNode() : prev;
    Node realNext = next.isVirtual() ? next.getRealNode() : next;
    for(Edge e : this._edges){
        if((e.getFrom() == realPrev && e.getTo() == realNext) ||
           (e.getFrom() == realNext && e.getTo() == realPrev)){
            return e;
        }
    }
    return null;
}

Edge edgeToNext() {
    Node current = this.currentNode;
    Node next = this.nextNode;
    if (current == null || next == null) {
        return null;
    }
    Node realCurrent = current.isVirtual() ? current.getRealNode() : current;
    Node realNext = next.isVirtual() ? next.getRealNode() : next;
    for (Edge e : this._edges) {
        if (e.getFrom() == realCurrent && e.getTo() == realNext) {
            return e;
        }
    }
